  // ---------- sortable (pointer events, drag & drop с перестановкой) ----------
  const COARSE = window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
  const DRAG_THRESHOLD = 6;

  function makeSortable(ul) {
    let li = null, pid = null, startX = 0, startY = 0, active = false, moved = false;

    ul.addEventListener("pointerdown", (e) => {
      const item = e.target.closest("li.item");
      if (!item || !ul.contains(item)) return;
      if (e.pointerType === "mouse" && e.button !== 0) return;
      if (COARSE && !e.target.closest(".handle")) return; // на тач-устройствах — за точки

      li = item;
      pid = e.pointerId;
      startX = e.clientX; startY = e.clientY;
      active = true; moved = false;
      try { li.setPointerCapture(pid); } catch (_) {}
    });

    ul.addEventListener("pointermove", (e) => {
      if (!active) return;
      const dx = e.clientX - startX, dy = e.clientY - startY;
      if (!moved) {
        if (Math.hypot(dx, dy) < DRAG_THRESHOLD) return;
        moved = true;
        li.classList.add("is-dragging");
      }
      if (e.cancelable) e.preventDefault();

      const t = document.elementFromPoint(e.clientX, e.clientY);
      if (!t) return;
      const target = t.closest && t.closest("li.item");
      if (!target || target === li || !ul.contains(target)) return;

      const rect = target.getBoundingClientRect();
      const before = (e.clientY - rect.top) < rect.height / 2;
      ul.insertBefore(li, before ? target : target.nextSibling);
      refreshPositionBadges();
    });

    const end = (e) => {
      if (!active) return;
      active = false;
      li.classList.remove("is-dragging");
      try { ul.releasePointerCapture(pid); } catch (_) {}
      refreshPositionBadges();
    };
    ul.addEventListener("pointerup", end);
    ul.addEventListener("pointercancel", end);

    // клавиатура: стрелки вверх/вниз
    ul.addEventListener("keydown", (e) => {
      if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
      const item = e.target.closest("li.item");
      if (!item) return;
      e.preventDefault();
      if (e.key === "ArrowUp" && item.previousElementSibling) ul.insertBefore(item, item.previousElementSibling);
      if (e.key === "ArrowDown" && item.nextElementSibling) ul.insertBefore(item.nextElementSibling, item);
      else if (e.key === "ArrowDown") ul.appendChild(item);
      item.focus({ preventScroll: true });
      refreshPositionBadges();
    });
  }

  // ---------- collect + score (как в оригинале: major = pos 0, minor = pos 3) ----------
  function collectPayload() {
    const payload = [];
    $$(".list", panesEl).forEach((ul, listIndex) => {
      Array.from(ul.children).forEach((li, idx) => {
        payload.push({ list: listIndex, pos: idx, type: li.getAttribute("data-type") });
      });
    });
    return payload;
  }

  function scoreOf(payload) {
    const maj = [], min = [];
    payload.forEach((x) => {
      if (x.pos === 0) maj.push(x.type);
      if (x.pos === 3) min.push(x.type);
    });
    const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
    return {
      d: count(maj, "d") - count(min, "d"),
      i: count(maj, "i") - count(min, "i"),
      s: count(maj, "s") - count(min, "s"),
      c: count(maj, "c") - count(min, "c")
    };
  }

  // ---------- finish ----------
  function resetQuiz() {
    QUIZ_DATA.forEach((cards, i) => {
      $$("ul.list", panes[i]).forEach((ul, j) => {
        const byText = new Map(Array.from(ul.children).map(li => [li.querySelector(".item__text").textContent, li]));
        ul.textContent = "";
        cards[j].forEach((it) => { if (byText.has(it[1])) ul.appendChild(byText.get(it[1])); });
      });
    });
    step = 0;
    finished = false;
    render();
  }

  btnFinish.addEventListener("click", () => {
    const res = scoreOf(collectPayload());
    const d = Number(res.d || 0), i = Number(res.i || 0),
          s = Number(res.s || 0), c = Number(res.c || 0);
    finished = true;
    closeWizard();
    scoreEl.textContent = "D:" + d + ", I:" + i + ", S:" + s + ", C:" + c;
    hero.hidden = true;
